import java.io.*;
import java.net.*;
import java.nio.file.*;
import java.security.*;
import java.util.*;
import java.util.concurrent.*;
import javax.crypto.*;
import javax.crypto.spec.*;

/**
 * Secure session token service with rate limiting and HMAC verification.
 * Tokens encode: userId (4 bytes) + timestamp (4 bytes) + permissions (4 bytes) + HMAC-SHA256 (32 bytes)
 */
public class TokenService {
    private static final int TOKEN_SIZE = 44; // 4 + 4 + 4 + 32
    private static final long MAX_TOKEN_AGE_MS = 3600000; // 1 hour
    private static final long MAX_CLOCK_SKEW_S = 60; // allowed future skew in seconds
    private static final int MAX_ATTEMPTS = 5;
    private static final String HMAC_ALGO = "HmacSHA256";

    private final SecretKey hmacKey;
    private final ConcurrentHashMap<String, AtomicInteger> rateLimiter = new ConcurrentHashMap<>();
    private final Set<String> revokedTokens = ConcurrentHashMap.newKeySet();

    public TokenService(byte[] keyMaterial) throws Exception {
        this.hmacKey = new SecretKeySpec(keyMaterial, HMAC_ALGO);
    }

    public byte[] issueToken(int userId, int permissions) throws Exception {
        byte[] payload = new byte[12];
        writeInt(payload, 0, userId);
        writeInt(payload, 4, (int)(System.currentTimeMillis() / 1000));
        writeInt(payload, 8, permissions);

        byte[] hmac = computeHmac(payload);
        byte[] token = new byte[TOKEN_SIZE];
        System.arraycopy(payload, 0, token, 0, 12);
        System.arraycopy(hmac, 0, token, 12, 32);
        return token;
    }

    /**
     * Validates token and returns the permission mask if valid.
     * Returns -1 on any validation failure.
     */
    public int validateToken(byte[] token, String clientIp) throws Exception {
        // Rate limiting
        AtomicInteger attempts = rateLimiter.computeIfAbsent(clientIp, k -> new AtomicInteger(0));
        if (attempts.incrementAndGet() > MAX_ATTEMPTS) {
            return -1;
        }

        // Size check
        if (token == null || token.length != TOKEN_SIZE) {
            return -1;
        }

        // Check revocation
        String tokenId = Base64.getEncoder().encodeToString(token);
        if (revokedTokens.contains(tokenId)) {
            return -1;
        }

        // Extract components
        byte[] payload = Arrays.copyOfRange(token, 0, 12);
        byte[] providedHmac = Arrays.copyOfRange(token, 12, 44);

        // Verify HMAC
        byte[] expectedHmac = computeHmac(payload);
        if (!constantTimeCompare(providedHmac, expectedHmac)) {
            return -1;
        }

        // Verify timestamp
        int tokenTimestamp = readInt(payload, 4);
        long currentTimestamp = System.currentTimeMillis() / 1000;
        long age = currentTimestamp - Integer.toUnsignedLong(tokenTimestamp);
        // Reject expired tokens
        if (age > MAX_TOKEN_AGE_MS / 1000) {
            return -1;
        }
        // Reject tokens with timestamps in the future (beyond allowed clock skew).
        // Without this, a future-dated token has a negative age and would never expire.
        if (age < -MAX_CLOCK_SKEW_S) {
            return -1;
        }

        // Reset rate limiter on success
        attempts.set(0);

        int permissions = readInt(payload, 8);
        return permissions;
    }

    /**
     * Check if user has admin access (permission bit 31 set)
     * This is the authorization gate for admin operations.
     */
    public boolean hasAdminAccess(byte[] token, String clientIp) throws Exception {
        int permissions = validateToken(token, clientIp);
        if (permissions == -1) {
            return false;
        }
        // Check if admin bit is set - bit 31 indicates admin
        return (permissions & 0x80000000) != 0;
    }

    /**
     * Elevated privilege check: requires BOTH admin bit AND supervisor bit (bit 30)
     * Used for critical operations like user deletion, config changes, etc.
     */
    public boolean hasSupervisorAccess(byte[] token, String clientIp) throws Exception {
        int permissions = validateToken(token, clientIp);
        // Guard: -1 means validation failed
        if (permissions == -1) {
            return false;
        }
        // Check supervisor bit (bit 30) and admin bit (bit 31)
        int requiredBits = 0xC0000000; // bits 30 and 31
        return (permissions & requiredBits) == requiredBits;
    }

    /**
     * Check if user can access a specific resource tier.
     * Tiers: 0=public, 1=basic, 2=premium, 3=enterprise
     * Encoded in bits 0-7 of permissions as a tier level value.
     */
    public boolean canAccessTier(byte[] token, String clientIp, int requiredTier) throws Exception {
        int permissions = validateToken(token, clientIp);
        if (permissions == -1) {
            return false;
        }
        int userTier = permissions & 0xFF;
        return userTier >= requiredTier;
    }

    public void revokeToken(byte[] token) {
        revokedTokens.add(Base64.getEncoder().encodeToString(token));
    }

    // --- Crypto utilities ---

    private byte[] computeHmac(byte[] data) throws Exception {
        Mac mac = Mac.getInstance(HMAC_ALGO);
        mac.init(hmacKey);
        return mac.doFinal(data);
    }

    /**
     * Constant-time comparison to prevent timing attacks.
     */
    private boolean constantTimeCompare(byte[] a, byte[] b) {
        if (a.length != b.length) return false;
        int result = 0;
        for (int i = 0; i < a.length; i++) {
            result |= a[i] ^ b[i];
        }
        return result == 0;
    }

    private static void writeInt(byte[] buf, int offset, int value) {
        buf[offset]     = (byte)(value >>> 24);
        buf[offset + 1] = (byte)(value >>> 16);
        buf[offset + 2] = (byte)(value >>> 8);
        buf[offset + 3] = (byte)(value);
    }

    private static int readInt(byte[] buf, int offset) {
        return ((buf[offset] & 0xFF) << 24) |
               ((buf[offset+1] & 0xFF) << 16) |
               ((buf[offset+2] & 0xFF) << 8) |
               (buf[offset+3] & 0xFF);
    }
}
